#include "ternet.hpp"
#include <cctype>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <map>
#include <sstream>
namespace fs=std::filesystem;
static fs::path mf(const std::string&d){return fs::path(d)/"ternet.toml";}
static std::map<std::string,std::string> deps(const fs::path&p){std::map<std::string,std::string>r;std::ifstream f(p);std::string line;bool on=false;while(std::getline(f,line)){if(line=="[dependencies]"){on=true;continue;}if(!line.empty()&&line[0]=='[')on=false;if(!on)continue;auto q=line.find('=');if(q==std::string::npos)continue;auto n=line.substr(0,q),v=line.substr(q+1);auto trim=[](std::string&s){while(!s.empty()&&std::isspace((unsigned char)s.back()))s.pop_back();size_t i=0;while(i<s.size()&&std::isspace((unsigned char)s[i]))++i;s=s.substr(i);if(s.size()>1&&s.front()=='"'&&s.back()=='"')s=s.substr(1,s.size()-2);};trim(n);trim(v);if(!n.empty())r[n]=v;}return r;}
int ternet::command_init(const std::string&d){fs::create_directories(fs::path(d)/"src");std::ofstream f(mf(d));f<<"[package]\nname = \"my_app\"\nversion = \"0.1.0\"\nedition = \"2026\"\nentry = \"Node.trn\"\n\n[dependencies]\n";std::ofstream n(fs::path(d)/"Node.trn");n<<"tnprint(\"Hello, Ternet\"):\n";std::ofstream s(fs::path(d)/"src/main.trn");s<<"// Secondary source entry.\n";std::cout<<"Created Ternet project in "<<d<<"\nEntry: Node.trn\n";return 0;}
int ternet::command_add(const std::string&d,const std::string&n,const std::string&v){if(!fs::exists(mf(d)))throw RuntimeError("ternet.toml not found; run 'tnc init'");std::ifstream in(mf(d));std::stringstream b;b<<in.rdbuf();std::string x=b.str();if(x.find("[dependencies]")==std::string::npos)x+="\n[dependencies]\n";x+=n+" = \""+v+"\"\n";std::ofstream out(mf(d));out<<x;std::cout<<"Added dependency "<<n<<" = "<<v<<"\n";return 0;}
int ternet::command_install(const std::string&d){if(!fs::exists(mf(d)))throw RuntimeError("ternet.toml not found");auto ds=deps(mf(d));fs::create_directories(fs::path(d)/".ternet/packages");std::ofstream l(fs::path(d)/"ternet.lock");l<<"# Generated by tnc install\n[packages]\n";for(auto&[n,v]:ds){l<<n<<" = \""<<v<<"\"\n";fs::create_directories(fs::path(d)/".ternet/packages"/n);std::ofstream m(fs::path(d)/".ternet/packages"/n/"package.toml");m<<"name = \""<<n<<"\"\nspec = \""<<v<<"\"\n";}std::cout<<"Resolved "<<ds.size()<<" package(s); lockfile written to ternet.lock\n";return 0;}
int ternet::command_remove(const std::string&d,const std::string&n){if(!fs::exists(mf(d)))throw RuntimeError("ternet.toml not found");std::ifstream in(mf(d));std::stringstream b;b<<in.rdbuf();std::string x=b.str(),needle=n+" = ";auto p=x.find(needle);if(p==std::string::npos)return 1;auto e=x.find('\n',p);x.erase(p,e==std::string::npos?x.size()-p:e-p+1);std::ofstream out(mf(d));out<<x;fs::remove_all(fs::path(d)/".ternet/packages"/n);std::cout<<"Removed dependency "<<n<<"\n";return 0;}
int ternet::command_list(const std::string&d){if(!fs::exists(mf(d)))throw RuntimeError("ternet.toml not found");auto ds=deps(mf(d));for(auto&[n,v]:ds)std::cout<<n<<" = "<<v<<"\n";if(ds.empty())std::cout<<"No dependencies.\n";return 0;}
int ternet::command_package(const std::string&d){if(!fs::exists(mf(d)))throw RuntimeError("ternet.toml not found");auto out=fs::path(d)/".ternet/package";fs::create_directories(out);std::ofstream m(out/"manifest.txt");m<<"Ternet package\n";for(auto&e:fs::recursive_directory_iterator(d))if(e.is_regular_file()&&e.path().filename()!="manifest.txt")m<<fs::relative(e.path(),d).string()<<"\n";std::cout<<"Package manifest created at "<<out<<"\n";return 0;}